// One digest for the week: an HTML table for the email and a short list for Slack.
const area = $('Set the area to watch').first().json;
const permits = $input.all().map((item) => item.json).filter((p) => p.reference);

const esc = (value) => String(value ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = (value) => (typeof value === 'number' ? '$' + Math.round(value).toLocaleString('en-US') : '');

const rows = permits.map((p) => ({
  issued: String(p.issued_date ?? '').slice(0, 10),
  address: [p.address, p.postal_code].filter(Boolean).join(', '),
  type: p.raw_type ?? '',
  work: String(p.description ?? '').slice(0, 160),
  value: usd(p.metrics?.project_value_usd),
  contractor: p.metrics?.contractor_business_name ?? '',
  link: p.metrics?.permit_url ?? '',
}));

const city = permits[0]?.authority_name ?? area.city;
const zips = area.zipCodes.length ? area.zipCodes.join(', ') : 'all ZIP codes';
const subject = `${rows.length} new building permits in ${city} (${zips})`;

const cell = (value) => `<td style="border-top:1px solid #e3e6eb;vertical-align:top">${value}</td>`;
const html = `<p>${esc(subject)}, issued in the last 7 days.</p>
<table cellpadding="6" style="border-collapse:collapse;font:13px Arial,sans-serif">
<tr style="background:#f1f3f6;text-align:left"><th>Issued</th><th>Address</th><th>Type</th><th>Work</th><th>Value</th><th>Contractor</th></tr>
${rows.map((r) => '<tr>' + [
    esc(r.issued),
    r.link ? `<a href="${esc(r.link)}">${esc(r.address)}</a>` : esc(r.address),
    esc(r.type), esc(r.work), esc(r.value), esc(r.contractor),
  ].map(cell).join('') + '</tr>').join('\n')}
</table>`;

const lines = rows.slice(0, 30).map((r) => `• ${[r.issued, r.address, r.type, r.value, r.contractor].filter(Boolean).join(' · ')}`);
if (rows.length > 30) lines.push(`…and ${rows.length - 30} more.`);
const text = [`*${subject}*`, ...lines].join('\n');

return [{ json: { subject, html, text, sendTo: area.sendTo, slackChannel: area.slackChannel } }];
